drop policy if exists "conversation participants read" on public.conversations;
create policy "active participants read conversations" on public.conversations for select to authenticated using((auth.uid()=user_a_id or auth.uid()=user_b_id) and exists(select 1 from connections c where c.id=connection_id) and not exists(select 1 from blocks b where (b.blocker_user_id=user_a_id and b.blocked_user_id=user_b_id) or (b.blocker_user_id=user_b_id and b.blocked_user_id=user_a_id)));
drop policy if exists "message participants read" on public.messages;
create policy "active participants read messages" on public.messages for select to authenticated using(exists(select 1 from conversations c where c.id=conversation_id and (auth.uid()=c.user_a_id or auth.uid()=c.user_b_id) and exists(select 1 from connections x where x.id=c.connection_id) and not exists(select 1 from blocks b where (b.blocker_user_id=c.user_a_id and b.blocked_user_id=c.user_b_id) or (b.blocker_user_id=c.user_b_id and b.blocked_user_id=c.user_a_id))));
create or replace function public.get_or_create_conversation(p_connection_id uuid) returns public.conversations language plpgsql security definer set search_path=public as $$ declare c public.connections; result public.conversations; begin if auth.uid() is null then raise exception 'unauthorized'; end if; select * into c from connections where id=p_connection_id and (user_a_id=auth.uid() or user_b_id=auth.uid()) and not exists(select 1 from blocks b where (b.blocker_user_id=user_a_id and b.blocked_user_id=user_b_id) or (b.blocker_user_id=user_b_id and b.blocked_user_id=user_a_id)); if not found then raise exception 'connection unavailable'; end if; select * into result from conversations where connection_id=p_connection_id; if result.id is null then insert into conversations(connection_id,user_a_id,user_b_id) values(c.id,c.user_a_id,c.user_b_id) returning * into result; end if; return result; end; $$;
create or replace function public.get_conversation_messages(p_conversation_id uuid) returns setof public.messages language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from conversations c join connections x on x.id=c.connection_id where c.id=p_conversation_id and (auth.uid()=c.user_a_id or auth.uid()=c.user_b_id) and not exists(select 1 from blocks b where (b.blocker_user_id=c.user_a_id and b.blocked_user_id=c.user_b_id) or (b.blocker_user_id=c.user_b_id and b.blocked_user_id=c.user_a_id))) then raise exception 'conversation unavailable'; end if; return query select * from messages where conversation_id=p_conversation_id order by created_at; end; $$;
create or replace function public.send_message(p_conversation_id uuid,p_body text,p_client_message_id text) returns public.messages language plpgsql security definer set search_path=public as $$ declare c public.conversations; existing public.messages; result public.messages; begin if auth.uid() is null or char_length(trim(p_body))=0 or char_length(p_body)>2000 then raise exception 'invalid message'; end if; select * into c from conversations where id=p_conversation_id and (user_a_id=auth.uid() or user_b_id=auth.uid()) and exists(select 1 from connections x where x.id=connection_id) and not exists(select 1 from blocks b where (b.blocker_user_id=user_a_id and b.blocked_user_id=user_b_id) or (b.blocker_user_id=user_b_id and b.blocked_user_id=user_a_id)); if not found then raise exception 'conversation unavailable'; end if; select * into existing from messages where sender_user_id=auth.uid() and client_message_id=p_client_message_id; if existing.id is not null then return existing; end if; insert into messages(conversation_id,sender_user_id,body,client_message_id) values(c.id,auth.uid(),trim(p_body),p_client_message_id) returning * into result; update conversations set last_message_at=result.created_at where id=c.id; insert into notifications(recipient_user_id,type,actor_user_id,entity_id,destination) values(case when c.user_a_id=auth.uid() then c.user_b_id else c.user_a_id end,'newMessage',auth.uid(),c.id::text,'/app/chat/'||c.id::text) on conflict do nothing; return result; end; $$;
revoke all on function public.get_or_create_conversation(uuid),public.get_conversation_messages(uuid),public.send_message(uuid,text,text) from public; grant execute on function public.get_or_create_conversation(uuid),public.get_conversation_messages(uuid),public.send_message(uuid,text,text) to authenticated;
